(function pjeInterceptaVisualizarAto() { 'use strict'; const log = (t, ...a) => console.log('%c[ATO-PROBE]', 'color:#06c;font-weight:bold', t, ...a); const warn = (t, ...a) => console.warn('%c[ATO-PROBE]', 'color:#a80;font-weight:bold', t, ...a); if (window.__atoProbeAtivo) { warn('Já existe um interceptador ativo. Recarregue a página antes de rodar de novo.'); return; } window.__atoProbeAtivo = true; const capturas = []; const IGNORAR = [ 'sockjs', 'websocket', '/bi/', 'google-analytics', 'gtm.js', '.png', '.jpg', '.svg', '.woff', '.css', '/assets/', ]; const deveIgnorar = (url) => IGNORAR.some((p) => String(url).toLowerCase().includes(p)); const registrar = (metodo, url, status, corpoReq, corpoRes) => { if (deveIgnorar(url)) return; const item = { t: new Date().toISOString().slice(11, 23), metodo, url: String(url), status, corpoReq, corpoRes, }; capturas.push(item); console.group(`%c ${metodo} ${status} `, 'background:#06c;color:#fff', String(url).replace(location.origin, '')); if (corpoReq) console.log('req:', corpoReq); if (corpoRes !== undefined) console.log('res:', corpoRes); console.groupEnd(); }; const fetchOrig = window.fetch; window.fetch = async function (...args) { const [input, init] = args; const url = typeof input === 'string' ? input : (input && input.url) || ''; const metodo = ((init && init.method) || (input && input.method) || 'GET').toUpperCase(); let corpoReq = (init && init.body) || null; try { if (corpoReq && typeof corpoReq === 'string') corpoReq = corpoReq.slice(0, 2000); } catch (_) {} const resp = await fetchOrig.apply(this, args); try { const clone = resp.clone(); const texto = await clone.text(); let corpoRes = texto; try { corpoRes = JSON.parse(texto); } catch (_) { corpoRes = texto.length > 3000 ? texto.slice(0, 3000) + '...[truncado]' : texto; } registrar(metodo, url, resp.status, corpoReq, corpoRes); } catch (_) { registrar(metodo, url, resp.status, corpoReq, '(corpo nao legivel)'); } return resp; }; const XHR = window.XMLHttpRequest; const openOrig = XHR.prototype.open; const sendOrig = XHR.prototype.send; XHR.prototype.open = function (metodo, url, ...resto) { this.__atoProbe = { metodo: String(metodo).toUpperCase(), url: String(url) }; return openOrig.call(this, metodo, url, ...resto); }; XHR.prototype.send = function (corpo) { const info = this.__atoProbe || {}; let corpoReq = corpo; try { if (corpoReq && typeof corpoReq === 'string') corpoReq = corpoReq.slice(0, 2000); } catch (_) {} this.addEventListener('load', () => { let corpoRes; try { const tipo = this.getResponseHeader('content-type') || ''; if (tipo.includes('json') || (this.responseText || '').trim().startsWith('{') || (this.responseText || '').trim().startsWith('[')) { corpoRes = JSON.parse(this.responseText); } else { const t = this.responseText || ''; corpoRes = t.length > 3000 ? t.slice(0, 3000) + '...[truncado]' : t; } } catch (_) { corpoRes = '(corpo nao parseavel)'; } registrar(info.metodo || 'GET', info.url || this.responseURL, this.status, corpoReq, corpoRes); }); return sendOrig.call(this, corpo); }; log('=== INTERCEPTADOR ARMADO ==='); log('Agora clique: envelope na linha da empresa -> "Detalhar Expediente" -> "Visualizar ato"'); log('Coletando por 10 segundos...'); setTimeout(() => { window.fetch = fetchOrig; XHR.prototype.open = openOrig; XHR.prototype.send = sendOrig; window.__atoProbeAtivo = false; console.group('%c ==== RESULTADO (10s) ==== ', 'background:#046;color:#fff;font-weight:bold'); log(`total de chamadas capturadas: ${capturas.length}`); const relevantes = capturas.filter((c) => { const u = c.url.toLowerCase(); return /expediente|notifica|ato|documento|domicilio|ciencia/.test(u); }); log(`candidatas (expediente|notifica|ato|documento|domicilio|ciencia): ${relevantes.length}`); console.table( capturas.map((c) => ({ t: c.t, metodo: c.metodo, status: c.status, url: c.url.replace(location.origin, '').slice(0, 130), })) ); console.group('%c SO AS CANDIDATAS ', 'background:#640;color:#fff;font-weight:bold'); for (const c of relevantes) { console.group(`${c.metodo} ${c.status} ${c.url.replace(location.origin, '')}`); if (c.corpoRes !== undefined) console.log('res:', c.corpoRes); if (c.corpoReq) console.log('req:', c.corpoReq); console.groupEnd(); } console.groupEnd(); console.group('%c BUSCA POR CAMPOS COM "id" DE NOTIFICAÇÃO ', 'background:#046;color:#fff;font-weight:bold'); const achados = []; const varrer = (obj, caminho, url) => { if (!obj || typeof obj !== 'object') return; for (const [k, v] of Object.entries(obj)) { const novo = `${caminho}.${k}`; if (/^id/i.test(k) && /notifica|ato|cientifica/i.test(k)) { achados.push({ url: url.replace(location.origin, ''), campo: novo, valor: v }); } if (v && typeof v === 'object') varrer(v, novo, url); } }; for (const c of capturas) { if (c.corpoRes && typeof c.corpoRes === 'object') varrer(c.corpoRes, '', c.url); } if (achados.length) { console.table(achados); } else { warn('Nenhum campo id*notifica* / id*ato* encontrado automaticamente.'); warn('Olhe a tabela de candidatas acima — o ID deve estar no corpo de uma delas.'); } console.groupEnd(); try { copy(JSON.stringify(capturas, null, 2)); log('Log completo copiado para a área de transferência.'); } catch (_) {} console.groupEnd(); window.__atoProbeCapturas = capturas; log('Acessível depois em: window.__atoProbeCapturas'); }, 10000); })();